#include "nect/core.hpp"
#include "nect/io.hpp"
#include <iostream>
#include <stdexcept>
using namespace nect;
int main(){int checks=0;auto check=[&](bool ok,const char* why){if(!ok)throw std::runtime_error(why);++checks;};try{auto d=empty_document("identity-document","comp","art");Object o;o.id="object";o.name="Original";o.source=default_primitive("source","nect.shape.rectangle");d.objects.emplace(o.id,o);d.compositions.front().roots={o.id};validate(d);const auto bytes=encode(d);Session first(d),second(d);check(!first.gesture_identity()&&!first.gesture_active(),"Inactive Session has no interaction identity");first.begin_gesture(0);const auto identity=first.gesture_identity();check(identity&&first.gesture_generation()==1&&first.document()==d&&encode(first.preview_document())==bytes,"Beginning creates ephemeral identity without authored delta");auto copy=first;check(copy.gesture_identity()==identity&&copy.gesture_generation()==first.gesture_generation(),"A Session copy represents the same original interaction");second.begin_gesture(0);check(second.gesture_generation()==first.gesture_generation()&&second.document()==first.document()&&second.gesture_identity()!=identity,"Independent equal-ID/revision/generation Session gets a distinct token");first.update_gesture({});check(first.gesture_identity()==identity&&encode(first.document())==bytes,"Empty preview retains exact token/source");first.update_gesture({Rename{"object","Changed"}});auto changed=d;changed.objects.at("object").name="Changed";check(first.preview_document()==changed&&first.gesture_identity()==identity,"Successful preview retains token and exact independently authored delta");bool failed=false;try{first.update_gesture({Rename{"missing","Invalid"}});}catch(const Error& e){failed=e.code=="MISSING_OBJECT";}check(failed&&first.preview_document()==changed&&first.gesture_identity()==identity,"Invalid update preserves admitted preview/token");first.commit_gesture();check(!first.gesture_identity()&&!first.gesture_active()&&first.document()==changed&&first.revision()==1&&first.history().current_id==1,"Successful commit retires token and admits one full authored History");check(copy.gesture_identity()==identity&&copy.preview_document()==d,"Committing one value-copy does not retire another same-interaction snapshot");second.cancel_gesture();check(!second.gesture_identity()&&!second.gesture_active()&&second.document()==d&&encode(second.document())==bytes,"Cancel clears token without authoring");second.begin_gesture(0);check(second.gesture_generation()==2&&second.gesture_identity()!=identity&&second.gesture_identity()!=copy.gesture_identity(),"New begin cannot reuse a retained retired ownership token");const auto next=second.gesture_identity();failed=false;try{second.begin_gesture(99);}catch(const Error& e){failed=e.code=="REVISION_CONFLICT";}check(failed&&second.gesture_identity()==next&&second.gesture_generation()==2&&second.preview_document()==d,"Failed revision preflight retains the live token/preview");Session limited(d,HistoryLimits{8,1});limited.begin_gesture(0);const auto admitted=limited.gesture_identity();limited.update_gesture({Rename{"object","Too large"}});auto too_large=d;too_large.objects.at("object").name="Too large";failed=false;try{limited.commit_gesture();}catch(const Error& e){failed=e.code=="HISTORY_LIMIT";}check(failed&&limited.gesture_identity()==admitted&&limited.gesture_active()&&limited.document()==d&&limited.preview_document()==too_large&&limited.revision()==0&&!limited.can_undo(),"Failed History admission keeps exact preview and ownership identity");limited.cancel_gesture();check(!limited.gesture_identity()&&limited.document()==d&&encode(limited.document())==bytes&&decode(bytes)==d,"Retiring a failed preview leaves native format/source unchanged");std::cout<<"PASS Session gesture identity "<<checks<<" checks\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<" after "<<checks<<" checks\n";return 1;}}
